CREATE TABLE organizations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, timezone text NOT NULL DEFAULT 'America/Toronto' CHECK(timezone='America/Toronto'), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text NOT NULL UNIQUE CHECK(email=lower(email)),password_hash text, name text NOT NULL DEFAULT '', disabled_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE organization_members(organization_id uuid NOT NULL REFERENCES organizations(id), user_id uuid NOT NULL REFERENCES users(id),role text NOT NULL DEFAULT 'admin' CHECK(role IN ('admin','editor')),PRIMARY KEY(organization_id,user_id));
CREATE TABLE staff_sessions(token_hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),organization_id uuid NOT NULL,expires_at timestamptz NOT NULL,FOREIGN KEY(organization_id,user_id) REFERENCES organization_members(organization_id,user_id));
CREATE INDEX sessions_expiry ON staff_sessions(expires_at);
CREATE TABLE account_tokens(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),email text NOT NULL,kind text NOT NULL CHECK(kind IN ('invite','reset')),token_hash text NOT NULL UNIQUE,expires_at timestamptz NOT NULL,used_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE rate_limits(key text PRIMARY KEY,count integer NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE screens(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),name text NOT NULL,location text NOT NULL DEFAULT '',orientation text NOT NULL DEFAULT 'portrait-cw' CHECK(orientation IN ('landscape','portrait-cw','portrait-ccw')),resolution text NOT NULL DEFAULT '',app_version text NOT NULL DEFAULT '',renderer_version integer NOT NULL DEFAULT 1,last_heartbeat timestamptz,last_ack jsonb,last_error jsonb,reset_pin_hash text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),revoked_at timestamptz,deleted_at timestamptz,UNIQUE(organization_id,id));
CREATE INDEX screens_org ON screens(organization_id) WHERE deleted_at IS NULL;
CREATE TABLE pairing_codes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code_hash text NOT NULL UNIQUE,challenge_hash text NOT NULL UNIQUE,device_token_hash text NOT NULL UNIQUE,expires_at timestamptz NOT NULL,claimed_at timestamptz,screen_id uuid REFERENCES screens(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE device_credentials(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,screen_id uuid NOT NULL,token_hash text NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now(),revoked_at timestamptz,FOREIGN KEY(organization_id,screen_id) REFERENCES screens(organization_id,id));
CREATE INDEX credentials_screen ON device_credentials(screen_id);
CREATE TABLE screen_groups(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),name text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,id),UNIQUE(organization_id,name));
CREATE TABLE screen_group_members(organization_id uuid NOT NULL,group_id uuid NOT NULL,screen_id uuid NOT NULL,PRIMARY KEY(group_id,screen_id),FOREIGN KEY(organization_id,group_id) REFERENCES screen_groups(organization_id,id) ON DELETE CASCADE,FOREIGN KEY(organization_id,screen_id) REFERENCES screens(organization_id,id));
CREATE TABLE media_assets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),name text NOT NULL,description text NOT NULL DEFAULT '',mime_type text NOT NULL,width integer NOT NULL,height integer NOT NULL,byte_size bigint NOT NULL CHECK(byte_size>0),sha256 text NOT NULL,storage_key text NOT NULL UNIQUE,thumbnail_key text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz,UNIQUE(organization_id,id));
CREATE TABLE designs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),name text NOT NULL,document jsonb NOT NULL,revision integer NOT NULL DEFAULT 1,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz,UNIQUE(organization_id,id));
CREATE TABLE design_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,design_id uuid NOT NULL,version integer NOT NULL,document jsonb NOT NULL,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(organization_id,design_id) REFERENCES designs(organization_id,id),UNIQUE(design_id,version),UNIQUE(organization_id,id));
CREATE TABLE templates(id text PRIMARY KEY,name text NOT NULL,document jsonb NOT NULL);
CREATE TABLE playlists(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),name text NOT NULL,revision integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz,UNIQUE(organization_id,id));
CREATE TABLE playlist_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,playlist_id uuid NOT NULL,design_version_id uuid,media_id uuid,position integer NOT NULL,duration integer NOT NULL CHECK(duration BETWEEN 2 AND 3600),CHECK((design_version_id IS NULL)<>(media_id IS NULL)),FOREIGN KEY(organization_id,playlist_id) REFERENCES playlists(organization_id,id),FOREIGN KEY(organization_id,design_version_id) REFERENCES design_versions(organization_id,id),FOREIGN KEY(organization_id,media_id) REFERENCES media_assets(organization_id,id),UNIQUE(playlist_id,position));
CREATE TABLE playlist_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,playlist_id uuid NOT NULL,version integer NOT NULL,snapshot jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(organization_id,playlist_id) REFERENCES playlists(organization_id,id),UNIQUE(playlist_id,version),UNIQUE(organization_id,id));
CREATE TABLE live_boards(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),name text NOT NULL,design_version_id uuid NOT NULL,data jsonb NOT NULL,revision integer NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(organization_id,design_version_id) REFERENCES design_versions(organization_id,id),UNIQUE(organization_id,id));
CREATE TABLE live_board_updates(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,live_board_id uuid NOT NULL,revision integer NOT NULL,data jsonb NOT NULL,actor_id uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(organization_id,live_board_id) REFERENCES live_boards(organization_id,id),UNIQUE(live_board_id,revision));
CREATE TABLE publication_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),actor_id uuid NOT NULL REFERENCES users(id),kind text NOT NULL,content_type text NOT NULL,content_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,id));
CREATE TABLE schedules(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),publication_id uuid NOT NULL,starts_at timestamptz NOT NULL,ends_at timestamptz,timezone text NOT NULL DEFAULT 'America/Toronto',cancelled_at timestamptz,CHECK(ends_at IS NULL OR ends_at>starts_at),FOREIGN KEY(organization_id,publication_id) REFERENCES publication_events(organization_id,id));
CREATE TABLE assignments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,screen_id uuid NOT NULL,publication_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN ('priority','schedule','normal','default')),design_version_id uuid,playlist_version_id uuid,live_board_id uuid,starts_at timestamptz NOT NULL DEFAULT now(),ends_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),cancelled_at timestamptz,CHECK(num_nonnulls(design_version_id,playlist_version_id,live_board_id)=1),CHECK(ends_at IS NULL OR ends_at>starts_at),FOREIGN KEY(organization_id,screen_id) REFERENCES screens(organization_id,id),FOREIGN KEY(organization_id,publication_id) REFERENCES publication_events(organization_id,id),FOREIGN KEY(organization_id,design_version_id) REFERENCES design_versions(organization_id,id),FOREIGN KEY(organization_id,playlist_version_id) REFERENCES playlist_versions(organization_id,id),FOREIGN KEY(organization_id,live_board_id) REFERENCES live_boards(organization_id,id));
CREATE INDEX assignment_resolution ON assignments(screen_id,starts_at,ends_at) WHERE cancelled_at IS NULL;
CREATE TABLE media_references(organization_id uuid NOT NULL,asset_id uuid NOT NULL,design_version_id uuid NOT NULL,PRIMARY KEY(asset_id,design_version_id),FOREIGN KEY(organization_id,asset_id) REFERENCES media_assets(organization_id,id),FOREIGN KEY(organization_id,design_version_id) REFERENCES design_versions(organization_id,id));
CREATE TABLE device_heartbeats(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,screen_id uuid NOT NULL REFERENCES screens(id),app_version text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE render_acknowledgements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),screen_id uuid NOT NULL REFERENCES screens(id),revision text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX acknowledgements_screen ON render_acknowledgements(screen_id,created_at DESC);
CREATE TABLE device_commands(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),screen_id uuid NOT NULL REFERENCES screens(id),kind text NOT NULL CHECK(kind='refresh'),created_at timestamptz NOT NULL DEFAULT now(),acknowledged_at timestamptz);
CREATE TABLE audit_logs(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,organization_id uuid NOT NULL REFERENCES organizations(id),actor_id uuid REFERENCES users(id),action text NOT NULL,entity_id text,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_org_time ON audit_logs(organization_id,created_at DESC);
CREATE FUNCTION immutable_content() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Published content and audit history are immutable'; END; $$;
CREATE TRIGGER immutable_design BEFORE UPDATE OR DELETE ON design_versions FOR EACH ROW EXECUTE FUNCTION immutable_content();
CREATE TRIGGER immutable_playlist BEFORE UPDATE OR DELETE ON playlist_versions FOR EACH ROW EXECUTE FUNCTION immutable_content();
CREATE TRIGGER immutable_audit BEFORE UPDATE OR DELETE ON audit_logs FOR EACH ROW EXECUTE FUNCTION immutable_content();
CREATE TRIGGER immutable_live_history BEFORE UPDATE OR DELETE ON live_board_updates FOR EACH ROW EXECUTE FUNCTION immutable_content();
